def top_k_and_rest_sorted(nums, k):
    s = sorted(nums)
    n = len(s)
    if k == 0:
        top = []
    else:
        top = s[n - k:]
        top.reverse()
    rest = s[:n - k]
    return (top, rest)

def sort_by_consonant_count(words):
