def count_distinct_prime_factors(n):
    distinct = set()
    d = 2
    remaining = n
    while d * d <= remaining:
        if remaining % d == 0:
            distinct.add(d)
            while remaining % d == 0:
                remaining //= d
        d += 1
    if remaining > 1:
        distinct.add(remaining)
    return len(distinct)

