import itertools
_MISSING = object()
def interleave_uneven(a, b):
    result = []
    for x, y in itertools.zip_longest(a, b, fillvalue=_MISSING):
        if x is not _MISSING:
            result.append(x)
        if y is not _MISSING:
            result.append(y)
    return result

