def is_valid_24h_time(s):
    parts = s.split(":")
    if len(parts) != 3:
        return False
    h, m, sec = parts
    if not (len(h) == 2 and h.isdigit() and len(m) == 2 and m.isdigit() and len(sec) == 2 and sec.isdigit()):
        return False
    hour, minute, second = int(h), int(m), int(sec)
    return 0 <= hour <= 23 and 0 <= minute <= 59 and 0 <= second <= 59

def partition_even_odd(lst):
